# Vorschlagsseite (noindex): immer NUR die aktuelle Runde, nie alte Listen mitliefern (Noah, 15.11.2026).
# Runde 7 (Noah mochte 6, 9, 20: Servus ich bin Noah + Brüder/Handwerksfirmen + ich weiß, wie es zugeht + abends keine Lust). Runde 6 (Aufbau nach Noah: Intro, Überleitung, einer der drei Familiensätze, Outro; Vorbild Felix auf zimmerei-partner.de, kürzer). Runde 5 (Runde 4 war Noah zu unauthentisch, Werbetexter-Sätze): Noahs eigene Sätze aus den Calls als Vorlage. Runde 4: komplette Über-uns-Sektionen (kleine Zeile, Überschrift, Text), HWM persönlich, SHK ohne Persönliches.
from pathlib import Path
import html
N = 'Noah Seelau, Gründer'
BLOECKE = [('Handwerksmanufaktur · Über uns, fester Teil', 'so steht er jetzt live', [('Über uns', 'Du bist auf der Baustelle daheim.|Wir im Internet.', 'Servus, ich bin Noah, Gründer der Handwerksmanufaktur. Dass wir nur fürs Handwerk arbeiten, kommt nicht von ungefähr. Meine drei Brüder haben alle im Handwerk gelernt. Zwei davon sind Meister. Zusätzlich haben wir in der Familie mehrere Handwerksbetriebe. Dadurch habe ich schon von klein auf täglich mitgekriegt, wie es im Handwerk wirklich zugeht. In den letzten 8 Jahren haben wir über 150 Firmen betreut und wissen mittlerweile ganz genau, …', '')]), ('Handwerksmanufaktur · Schlusssatz', 'In den letzten 8 Jahren haben wir über 150 Firmen betreut und wissen mittlerweile ganz genau, …', [('Schlusssatz', '', '… wie ein Handwerksbetrieb planbar an Aufträge und gute Mitarbeiter kommt.', ''), ('Schlusssatz', '', '… wie wir dir Aufträge und Mitarbeiter in den Betrieb holen.', ''), ('Schlusssatz', '', '… was bei Kunden und Bewerbern im Handwerk ankommt und was nicht.', ''), ('Schlusssatz', '', '… wie wir deinen Betrieb so zeigen, dass die richtigen Kunden und Bewerber anfragen.', ''), ('Schlusssatz', '', '… wo es bei Aufträgen und Mitarbeitern hakt und wie wir das lösen.', ''), ('Schlusssatz', '', '… wie wir für dich Anfragen und Bewerbungen aus deinem Umkreis holen.', ''), ('Schlusssatz', '', '… was ein Handwerksbetrieb online braucht, damit Kunden und Bewerber bei ihm landen.', ''), ('Schlusssatz', '', '… wie man im Handwerk Kunden und Fachkräfte erreicht und überzeugt.', ''), ('Schlusssatz', '', '… wie wir dir die Arbeit mit Website, Anzeigen und Bewerbungen abnehmen.', ''), ('Schlusssatz', '', '… welche Website und welche Anzeige bei deinen Kunden und Bewerbern wirklich zieht.', '')]), ('Handwerksmanufaktur · Unterzeile ganz oben', 'unter „Dein Handwerk. Unsere Baustelle.“, ohne 2019, 150 und Google', [('Unterzeile', '', 'Wir bauen deine Website und bringen dir Kunden und Mitarbeiter aus deinem Umkreis.', ''), ('Unterzeile', '', 'Website, neue Kunden und neue Mitarbeiter. Du machst dein Handwerk, den Rest übernehmen wir.', ''), ('Unterzeile', '', 'Wir kümmern uns um Website, Anfragen und Bewerbungen, damit du dich um deine Baustellen kümmern kannst.', ''), ('Unterzeile', '', 'Wir sorgen dafür, dass man dich online findet und Anfragen und Bewerbungen reinkommen.', ''), ('Unterzeile', '', 'Website, Anzeigen und Google aus einer Hand. Für Kunden und Mitarbeiter aus deinem Umkreis.', ''), ('Unterzeile', '', 'Neue Kunden und neue Mitarbeiter aus deinem Umkreis, dazu eine Website, die Anfragen bringt.', ''), ('Unterzeile', '', 'Wir bringen deinen Betrieb ins Internet und Kunden und Mitarbeiter zu dir.', ''), ('Unterzeile', '', 'Mehr Anfragen, mehr Bewerbungen und eine Website, die zu deinem Betrieb passt.', ''), ('Unterzeile', '', 'Wir übernehmen Website, Anzeigen und Bewerbersuche. Du führst nur noch die Gespräche.', ''), ('Unterzeile', '', 'Damit dein Betrieb online so gut dasteht wie auf der Baustelle.', '')]), ('SHK · Unterzeile Über uns', 'unter „Marketing für Handwerksbetriebe, seit 2019.“', [('Unterzeile', '', 'Wir holen SHK-Betrieben Monteure und Aufträge für Bad und Wärmepumpe, gedreht mit deinen eigenen Leuten.', ''), ('Unterzeile', '', 'Anzeigen für Monteure und Aufträge, mit Videos aus deinem Betrieb und deinem Team.', ''), ('Unterzeile', '', 'Wir sorgen dafür, dass Monteure und Aufträge aus deinem Umkreis planbar kommen.', ''), ('Unterzeile', '', 'Monteure, Bad-Aufträge, Wärmepumpen. Wir machen die Anzeigen, du führst die Gespräche.', ''), ('Unterzeile', '', 'Für Betriebe aus Sanitär, Heizung und Klima. Wir finden Monteure und holen dir Aufträge.', ''), ('Unterzeile', '', 'Wir drehen bei dir im Betrieb und machen daraus Anzeigen für Monteure und Aufträge.', ''), ('Unterzeile', '', 'Damit Monteure und Aufträge nicht mehr vom Zufall abhängen.', ''), ('Unterzeile', '', 'Wir bringen dein Angebot zu Monteuren und Bauherren in deinem Umkreis.', ''), ('Unterzeile', '', 'Neue Monteure und Aufträge für Bad und Wärmepumpe, mit Anzeigen, die nach deinem Betrieb aussehen.', ''), ('Unterzeile', '', 'Wir übernehmen Anzeigen, Videos und Website, damit Bewerbungen und Anfragen regelmäßig reinkommen.', '')]), ('SHK · Schlusssatz Über-uns-Text', 'gleicher fester Teil wie oben, dann In den letzten 8 Jahren haben wir über 150 Firmen betreut und wissen mittlerweile ganz genau, …', [('Schlusssatz', '', '… wie ein SHK-Betrieb planbar an Monteure und Aufträge kommt.', ''), ('Schlusssatz', '', '… wie wir für dich Monteure und Aufträge für Bad und Wärmepumpe aus deinem Umkreis holen.', ''), ('Schlusssatz', '', '… womit man einen Anlagenmechaniker erreicht und wann jemand sein Bad sanieren will.', ''), ('Schlusssatz', '', '… wo es bei Monteuren und Aufträgen hakt und wie wir das lösen.', ''), ('Schlusssatz', '', '… welche Anzeige bei Monteuren ankommt und welche bei Bauherren, die ein neues Bad wollen.', ''), ('Schlusssatz', '', '… wie wir deinen Betrieb so zeigen, dass gute Monteure und passende Aufträge anfragen.', ''), ('Schlusssatz', '', '… wie man Monteure erreicht, die gerade woanders in Arbeit sind.', ''), ('Schlusssatz', '', '… was ein SHK-Betrieb braucht, damit Bewerbungen und Anfragen regelmäßig reinkommen.', ''), ('Schlusssatz', '', '… wie wir dir Monteure und Aufträge holen, ohne dass du dich um Anzeigen kümmern musst.', ''), ('Schlusssatz', '', '… wie du Monteure und Aufträge bekommst, ohne auf Empfehlungen zu warten.', '')])]
e = html.escape
def h(x):
    a, _, b = x.partition('|')
    return e(a) + (f'<br><em>{e(b)}</em>' if b else '')
out = ['<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Über-uns-Texte</title><style>'
 ':root{--ink:#0B1424;--sub:#4A5666;--line:#DCE3EC;--paper:#F3F6FA;--warm:#C9581A}*{box-sizing:border-box;margin:0;padding:0}body{background:var(--paper);color:var(--ink);font:17px/1.55 Inter,system-ui,-apple-system,sans-serif;-webkit-font-smoothing:antialiased}'
 '.wrap{max-width:760px;margin:0 auto;padding:32px 20px 96px}h1{font-size:clamp(30px,5vw,44px);letter-spacing:-.03em;line-height:1.1;margin-bottom:8px}.lead{color:var(--sub)}h2{font-size:24px;letter-spacing:-.02em;margin:56px 0 16px}h2 small{display:block;font-size:15px;font-weight:400;letter-spacing:0;color:var(--sub);margin-top:4px}'
 '.k{background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px;margin-bottom:16px;position:relative}.nr{position:absolute;top:28px;right:32px;font-size:15px;font-weight:600;color:var(--sub)}.kl{font-size:14px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--warm);margin-bottom:16px}'
 '.k h3{font-size:clamp(28px,5vw,38px);line-height:1.1;letter-spacing:-.03em;margin-bottom:20px;text-wrap:balance}.k h3 em{font-style:italic;font-weight:500;color:var(--warm)}.k p{color:var(--sub);max-width:58ch}.k .sig{margin-top:20px;color:var(--ink);font-weight:600;font-size:15px}'
 '@media(max-width:560px){.k{padding:24px 20px}.nr{top:20px;right:20px}}'
 '</style></head><body><div class="wrap"><h1>Über-uns-Texte</h1><p class="lead">Nenn mir Seite und Nummer.</p>']
for titel, dom, liste in BLOECKE:
    out.append(f'<h2>{e(titel)}<small>{e(dom)}</small></h2>')
    for i, (kl, hh, tx, sig) in enumerate(liste, 1):
        out.append(f'<div class="k"><span class="nr">{i}</span><div class="kl">{e(kl)}</div>' + (f'<h3 style="margin-bottom:0">{h(hh)}</h3>' if hh else '') + (f'<p>{e(tx)}</p>' if tx else '') + (f'<p class="sig">{e(sig)}</p>' if sig else '') + '</div>')
out.append('</div></body></html>')
s = ''.join(out)
assert '–' not in s and '—' not in s and 'sondern' not in s and 'komme aus einer' not in s and 'keine Lust' not in s
Path(__file__).with_name('index.html').write_text(s)
print(sum(len(l) for _, _, l in BLOECKE), 'Texte')
